static inline int getTextWidthHD(const char* str, bool large = false) {
    if (!str) return 0;
    const GlyphHD* table = large ? g_fontHD_Large : g_fontHD_Regular;
    int total = 0;
    for (const uint8_t* p = (const uint8_t*)str; *p; ) {
        uint8_t c = *p;
        if (c < 128) {
            if (table[c].data) total += table[c].w;
            else total += (large ? 18 : 11);
            p++;
        } else if ((c & 0xE0) == 0xC0 && p[1] != 0) {
            total += (large ? 14 : 10);
            p += 2;
        } else if ((c & 0xF0) == 0xE0 && p[1] != 0 && p[2] != 0) {
            total += (large ? 16 : 12);
            p += 3;
        } else {
            total += (large ? 14 : 10);
            p++;
        }
    }
    return total;
}

// High-contrast alpha blend pixel (src over dst) for razor-sharp 1080p text
static inline void blendPxHD(uint32_t* fb, int x, int y, uint32_t col, uint8_t alpha) {
    if ((unsigned)x >= 1920u || (unsigned)y >= 1080u || alpha < 16) return;
    uint32_t* p = fb + (size_t)y * 1920 + x;
    // Boost contrast curve so glyph stems are 100% solid and edges are crisp
    uint32_t sharpA = ((uint32_t)alpha * 320u) >> 8;
    if (sharpA >= 250u) {
        *p = col;
        return;
    }
    uint32_t dst = *p;
    uint32_t r1 = (col >> 16) & 0xff, g1 = (col >> 8) & 0xff, b1 = col & 0xff;
    uint32_t r0 = (dst >> 16) & 0xff, g0 = (dst >> 8) & 0xff, b0 = dst & 0xff;
    uint32_t inv = 255u - sharpA;
    uint32_t r = (r1 * sharpA + r0 * inv) >> 8;
    uint32_t g = (g1 * sharpA + g0 * inv) >> 8;
    uint32_t b = (b1 * sharpA + b0 * inv) >> 8;
    *p = 0xff000000 | (r << 16) | (g << 8) | b;
}

// Draw crisp anti-aliased TrueType text
static inline void drawTextHDRaw(uint32_t* fb, int x, int y, const char* str, uint32_t col, bool large = false, int maxPxWidth = 99999, bool isShadowPass = false) {
    if (!str) return;
    const GlyphHD* table = large ? g_fontHD_Large : g_fontHD_Regular;
    
    // Auto-truncate with "..." if exceeding maxPxWidth
    int totalW = getTextWidthHD(str, large);
    char buf[256];
    const char* renderStr = str;
    if (totalW > maxPxWidth && maxPxWidth > 32) {
        int dotW = getTextWidthHD("...", large);
        int curW = 0;
        int i = 0;
        for (; str[i] && i < 248; ) {
            uint8_t c = (uint8_t)str[i];
            int charBytes = 1;
            int cw = (large ? 18 : 11);
            if (c < 128) {
                if (table[c].data) cw = table[c].w;
            } else if ((c & 0xE0) == 0xC0 && str[i + 1]) {
                charBytes = 2;
                cw = (large ? 14 : 10);
            } else if ((c & 0xF0) == 0xE0 && str[i + 1] && str[i + 2]) {
                charBytes = 3;
                cw = (large ? 16 : 12);
            }
            if (curW + cw + dotW > maxPxWidth) break;
            for (int b = 0; b < charBytes; b++) buf[i + b] = str[i + b];
            i += charBytes;
            curW += cw;
        }
        buf[i++] = '.'; buf[i++] = '.'; buf[i++] = '.'; buf[i] = '\0';
        renderStr = buf;
    }

    int curX = x;
    int lineH = large ? 39 : 25;
    for (const uint8_t* p = (const uint8_t*)renderStr; *p; ) {
        uint8_t c = *p;
        if (c >= 128) {
            int adv = (large ? 16 : 12);
            int step = 1;
            if ((c & 0xE0) == 0xC0 && p[1]) { adv = (large ? 14 : 10); step = 2; }
            else if ((c & 0xF0) == 0xE0 && p[1] && p[2]) { adv = (large ? 16 : 12); step = 3; }

            // Draw crisp centered separator dot for UTF-8 bullet/middle-dot
            int dotCx = curX + adv / 2;
            int dotCy = y + (lineH * 52) / 100;
            int dotR = large ? 3 : 2;
            for (int dy = -dotR; dy <= dotR; dy++) {
                for (int dx = -dotR; dx <= dotR; dx++) {
                    if (dx * dx + dy * dy <= dotR * dotR + 1) {
                        blendPxHD(fb, dotCx + dx, dotCy + dy, col, isShadowPass ? 180 : 255);
                    }
                }
            }
            curX += adv;
            p += step;
            if (curX >= 1920) break;
            continue;
        }
        if (!table[c].data) {
            curX += (large ? 18 : 11);
            p++;
            continue;
        }
        const GlyphHD& g = table[c];
        const uint8_t* src = g.data;
        uint8_t minAlpha = isShadowPass ? 128 : 24;
        for (int r = 0; r < g.h; r++) {
            int py = y + r;
            if ((unsigned)py >= 1080u) continue;
            for (int colIdx = 0; colIdx < g.w; colIdx++) {
                uint8_t a = src[r * g.w + colIdx];
                if (a >= minAlpha) {
                    blendPxHD(fb, curX + colIdx, py, col, isShadowPass ? 210 : a);
                }
            }
        }
        curX += g.w;
        p++;
        if (curX >= 1920) break;
    }
}

// Draw with crisp drop-shadow on core strokes only (eliminates blurry edge halo)
static inline void drawTextHD(uint32_t* fb, int x, int y, const char* str, uint32_t col, bool large = false, int maxPxWidth = 99999) {
    if (!str) return;
    int sh = large ? 2 : 1;
    drawTextHDRaw(fb, x + sh, y + sh, str, 0xff040810, large, maxPxWidth, true);
    drawTextHDRaw(fb, x, y, str, col, large, maxPxWidth, false);
}

static inline void drawTextHDCentered(uint32_t* fb, int cx, int y, const char* str, uint32_t col, bool large = false, int maxPxWidth = 99999) {
    if (!str) return;
    int totalW = getTextWidthHD(str, large);
    if (totalW > maxPxWidth) totalW = maxPxWidth;
    drawTextHD(fb, cx - totalW / 2, y, str, col, large, maxPxWidth);
}

static inline void drawTextHDRight(uint32_t* fb, int rightX, int y, const char* str, uint32_t col, bool large = false, int maxPxWidth = 99999) {
    if (!str) return;
    int totalW = getTextWidthHD(str, large);
    if (totalW > maxPxWidth) totalW = maxPxWidth;
    drawTextHD(fb, rightX - totalW, y, str, col, large, maxPxWidth);
}
